import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./RiverDashboard.css";

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

// ---------------------------------------------------------
// 📍 COMPONENT 1: Map Popup (Same as before)
// ---------------------------------------------------------
const LocationPopup = ({ lat, lon, depth, explanation }) => {
  const [address, setAddress] = useState("Loading...");
  const [placeName, setPlaceName] = useState("");

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`;
        const res = await axios.get(url);
        if (res.data && res.data.address) {
          const addr = res.data.address;
          const fullAddress = [
             addr.road, 
             addr.suburb || addr.neighbourhood, 
             addr.village || addr.town, 
             addr.state
          ].filter(Boolean).join(", ");
          
          setAddress(fullAddress);
          setPlaceName(addr.village || addr.town || "Unknown Location");
        }
      } catch (err) { setAddress("Address unavailable"); }
    };
    fetchAddress();
  }, [lat, lon]);

  return (
    <div className="popup-content">
      <strong>{placeName || "Flood Point"}</strong>
      <hr style={{margin: '5px 0', border: '0', borderTop: '1px solid #ccc'}}/>
      <div><span className="label">Depth:</span> <strong style={{color:'#ef4444'}}>{depth}m</strong></div>
      <div><span className="label">Status:</span> {explanation}</div>
      <div style={{fontSize:'11px', marginTop:'5px', color:'#555'}}>{address}</div>
    </div>
  );
};

// ---------------------------------------------------------
// 📋 COMPONENT 2: User-Friendly List Item
// ---------------------------------------------------------
const AffectedAreaItem = ({ data }) => {
  const [expanded, setExpanded] = useState(false);
  const [details, setDetails] = useState(null);
  const [loading, setLoading] = useState(false);

  // Simple color coding for locals
  const isSevere = data.depth >= 1.5;
  const cardColor = isSevere ? "#fee2e2" : "#fff7ed"; // Light Red vs Light Orange
  const borderColor = isSevere ? "#ef4444" : "#f59e0b";
  const icon = isSevere ? "fa-exclamation-triangle" : "fa-water";

  const fetchDetails = async () => {
    if (!expanded && !details) {
      setLoading(true);
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${data.lat}&lon=${data.lon}`;
        const res = await axios.get(url);
        if (res.data && res.data.address) {
            setDetails(res.data.address);
        }
      } catch (e) { setDetails({ error: true }); }
      finally { setLoading(false); }
    }
    setExpanded(!expanded);
  };

  return (
    <div style={{
      background: 'rgba(255, 255, 255, 0.95)',
      borderRadius: '12px',
      marginBottom: '12px',
      borderLeft: `6px solid ${borderColor}`,
      padding: '15px',
      color: '#333',
      boxShadow: '0 4px 6px rgba(0,0,0,0.1)'
    }}>
      {/* HEADER ROW */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          <div style={{ 
            background: borderColor, 
            color: 'white', 
            width: '40px', height: '40px', 
            borderRadius: '50%', 
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '1.2rem'
          }}>
            <i className={`fas ${icon}`}></i>
          </div>
          <div>
            <h4 style={{ margin: 0, fontSize: '1.1rem', color: '#1e293b' }}>
              {data.place || "Unknown Village"}
            </h4>
            <span style={{ fontSize: '0.9rem', color: '#64748b' }}>
              Water Level: <strong>{data.depth}m</strong> • {isSevere ? "Danger Zone" : "Waterlogging"}
            </span>
          </div>
        </div>

        <button 
          onClick={fetchDetails}
          style={{
            padding: '8px 15px',
            background: expanded ? '#e2e8f0' : '#3b82f6',
            color: expanded ? '#475569' : 'white',
            border: 'none',
            borderRadius: '20px',
            cursor: 'pointer',
            fontWeight: '600',
            fontSize: '0.85rem',
            transition: 'all 0.2s'
          }}
        >
          {expanded ? "Close" : "Get Exact Location"}
        </button>
      </div>

      {/* EXPANDED ADDRESS DETAILS */}
      {expanded && (
        <div style={{ marginTop: '15px', paddingTop: '10px', borderTop: '1px solid #e2e8f0', fontSize: '0.95rem' }}>
          {loading ? (
            <div style={{color: '#64748b'}}><i className="fas fa-spinner fa-spin"></i> Finding address...</div>
          ) : details ? (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
               <div><small style={{color:'#94a3b8'}}>ROAD / STREET</small><br/><strong>{details.road || "N/A"}</strong></div>
               <div><small style={{color:'#94a3b8'}}>NEIGHBORHOOD</small><br/><strong>{details.suburb || details.neighbourhood || "N/A"}</strong></div>
               <div><small style={{color:'#94a3b8'}}>VILLAGE / TOWN</small><br/><strong>{details.village || details.town || "N/A"}</strong></div>
               <div><small style={{color:'#94a3b8'}}>LANDMARK</small><br/><strong>{details.public_building || details.amenity || "Near " + (details.road || "Location")}</strong></div>
            </div>
          ) : (
            <div style={{color:'red'}}>Address not found.</div>
          )}
        </div>
      )}
    </div>
  );
};

// ---------------------------------------------------------
// 🚀 MAIN PAGE
// ---------------------------------------------------------
const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);
  
  // 🔥 NEW STATE FOR TOGGLING
  const [showAllAreas, setShowAllAreas] = useState(false);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, {
          params: { level: simulatedLevel } 
        });
        if (response.data) {
           // Sort by depth (Deepest first)
           if(response.data.data) response.data.data.sort((a,b) => b.depth - a.depth);
           setFloodData(response.data);
        }
      } catch (error) { console.error(error); } 
      finally { setLoading(false); }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Scanning Area...</p></div>;

  // 🔴 FILTER LOGIC: Split into Severe and Others
  const severeZones = floodData?.data?.filter(d => d.depth >= 1.5) || [];
  const otherZones = floodData?.data?.filter(d => d.depth < 1.5) || [];

  return (
    <div className="rd-container">
      <nav className="rd-nav-overlay">
        <div className="rd-wrapper rd-flex-between">
            <div className="rd-brand">Periyar<span>Watch</span></div>
            <button onClick={() => navigate('/')} className="nav-btn"><i className="fas fa-arrow-left"></i> Home</button>
        </div>
      </nav>

      <main className="rd-main-content rd-wrapper" style={{marginTop: '90px'}}>
        
        {/* HEADER */}
        <div style={{textAlign: 'center', marginBottom: '30px'}}>
          <h2 style={{fontSize: '2rem', marginBottom:'5px'}}>Flood Impact Map</h2>
          <p style={{opacity: 0.8}}>Showing areas affected if water reaches <strong>{floodData?.current_water_level}m</strong></p>
        </div>

        {/* MAP */}
        <section className="rd-section glass" style={{height: '500px', marginBottom: '40px', padding:'5px'}}>
          <MapContainer center={[10.16, 76.43]} zoom={13} style={{ height: "100%", width: "100%", borderRadius: "8px" }}>
              <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution='&copy; OpenStreetMap' />
              {floodData?.data?.map((point, idx) => (
                  <CircleMarker 
                      key={idx} center={[point.lat, point.lon]} radius={6}
                      pathOptions={{ color: 'white', weight:1, fillColor: point.depth >= 1.5 ? '#ef4444' : '#f59e0b', fillOpacity: 0.8 }}
                  >
                      <Popup><LocationPopup {...point} /></Popup>
                  </CircleMarker>
              ))}
          </MapContainer>
        </section>

        {/* 🚨 SEVERE ALERTS SECTION (Always Visible) */}
        {severeZones.length > 0 && (
          <section className="rd-section" style={{ borderTop: 'none' }}>
            <div style={{ 
              background: '#ef4444', color: 'white', padding: '15px', borderRadius: '10px 10px 0 0',
              display: 'flex', alignItems: 'center', gap: '10px'
            }}>
              <i className="fas fa-bullhorn" style={{fontSize:'1.5rem'}}></i>
              <div>
                <h3 style={{margin:0, fontSize:'1.2rem'}}>Severe Danger Zones ({severeZones.length})</h3>
                <small>Evacuation recommended for these areas.</small>
              </div>
            </div>
            
            <div style={{ background: 'rgba(239, 68, 68, 0.1)', padding: '20px', borderRadius: '0 0 10px 10px' }}>
              {severeZones.map((item, index) => (
                <AffectedAreaItem key={index} data={item} />
              ))}
            </div>
          </section>
        )}

        {/* 🟡 MODERATE / OTHER ZONES (Collapsible) */}
        {otherZones.length > 0 && (
          <section style={{ marginTop: '30px', marginBottom: '50px' }}>
            
            {/* TOGGLE DROPDOWN BUTTON */}
            <button 
              onClick={() => setShowAllAreas(!showAllAreas)}
              style={{
                width: '100%',
                padding: '15px',
                background: showAllAreas ? '#f59e0b' : 'rgba(255,255,255,0.1)',
                border: '2px solid #f59e0b',
                color: showAllAreas ? 'black' : '#f59e0b',
                borderRadius: '10px',
                cursor: 'pointer',
                fontSize: '1rem',
                fontWeight: 'bold',
                display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px',
                transition: 'all 0.3s'
              }}
            >
              {showAllAreas ? (
                <><i className="fas fa-chevron-up"></i> Hide Moderate Impact Areas</>
              ) : (
                <><i className="fas fa-chevron-down"></i> View {otherZones.length} Other Affected Areas (Moderate/Minor)</>
              )}
            </button>

            {/* EXPANDABLE LIST */}
            {showAllAreas && (
              <div style={{ marginTop: '20px', animation: 'fadeIn 0.5s' }}>
                 <p style={{color:'#ccc', marginBottom:'15px', textAlign:'center'}}>
                   These areas may experience road blocks or yard flooding but are less critical than the red zones above.
                 </p>
                 {otherZones.slice(0, 50).map((item, index) => (
                    <AffectedAreaItem key={index} data={item} />
                 ))}
                 {otherZones.length > 50 && (
                   <div style={{textAlign:'center', color:'#888', marginTop:'10px'}}>
                     ...and {otherZones.length - 50} more minor points.
                   </div>
                 )}
              </div>
            )}
          </section>
        )}

        {floodData?.data?.length === 0 && (
           <div style={{textAlign:'center', padding:'50px', color:'#10b981'}}>
             <h3><i className="fas fa-shield-alt"></i> Safe Status</h3>
             <p>No affected areas detected at this water level.</p>
           </div>
        )}

      </main>
    </div>
  );
};

export default FloodMap;
